var postorderTraversal = function(root) {
    if (root === null) return [];
    const res = [];
    const stack = [root];
    while (stack.length > 0) {
        const node = stack.pop();
        res.push(node.val);
        if (node.left !== null) stack.push(node.left);
        if (node.right !== null) stack.push(node.right);
    }
    return res.reverse();
};
